import * as fs from 'fs';
import { detectFfmpeg, probeMedia } from './mediaProbe.js';
import { runFfmpeg } from './videoExporter.js';

/**
 * Phase 29: AI-assisted editing suggestions from REAL signal
 * analysis — nothing here is generated by a language model and
 * nothing is invented:
 *
 * - Scene detection runs ffmpeg's scene-score filter and reports
 *   the timestamps whose frame-difference score passes a threshold.
 * - Silence detection runs ffmpeg's silencedetect and reports the
 *   actual silent spans.
 * - Suggested cuts are a deterministic combination of the two:
 *   scene boundaries are suggested cut points; silent spans longer
 *   than the minimum are suggested removals.
 *
 * If ffmpeg or the media is unavailable, the result is an explicit
 * error — never an empty-but-confident answer.
 */

export interface SilenceSpan {
  startSec: number;
  endSec: number;
}

export interface SuggestedCut {
  startSec: number;
  endSec: number;
  reason: 'silence' | 'scene-boundary';
}

export interface AnalysisResult {
  status: 'success' | 'error';
  error?: string;
  durationSec?: number;
  sceneChangesSec?: number[];
  silences?: SilenceSpan[];
  suggestedCuts?: SuggestedCut[];
}

export interface AnalysisOptions {
  sceneThreshold?: number;
  silenceNoiseDb?: number;
  silenceMinDurationSec?: number;
  timeoutMs?: number;
}

export async function analyzeMedia(mediaPath: string, options: AnalysisOptions = {}): Promise<AnalysisResult> {
  const ffmpeg = detectFfmpeg();
  if (!ffmpeg) return { status: 'error', error: 'ffmpeg not found on this host; media analysis requires ffmpeg.' };
  if (!fs.existsSync(mediaPath)) return { status: 'error', error: `Media file missing: ${mediaPath}` };
  let probe;
  try {
    probe = await probeMedia(mediaPath);
  } catch (e: any) {
    return { status: 'error', error: `Could not probe media: ${e.message}` };
  }
  const timeoutMs = options.timeoutMs ?? 600_000;
  const sceneThreshold = options.sceneThreshold ?? 0.4;
  const noiseDb = options.silenceNoiseDb ?? -35;
  const minSilence = options.silenceMinDurationSec ?? 0.6;

  const sceneChangesSec: number[] = [];
  if (probe.hasVideo) {
    const { code, log } = await runFfmpeg(
      ffmpeg,
      ['-i', mediaPath, '-filter:v', `select='gt(scene,${sceneThreshold})',showinfo`, '-f', 'null', '-'],
      timeoutMs
    );
    if (code !== 0) return { status: 'error', error: `Scene detection failed (ffmpeg exit ${code}); the media may be corrupted.`, };
    for (const match of log.matchAll(/pts_time:([0-9.]+)/g)) {
      const t = Number(match[1]);
      if (t > 0.05) sceneChangesSec.push(Number(t.toFixed(3)));
    }
  }

  const silences: SilenceSpan[] = [];
  if (probe.hasAudio) {
    const { code, log } = await runFfmpeg(
      ffmpeg,
      ['-i', mediaPath, '-af', `silencedetect=noise=${noiseDb}dB:d=${minSilence}`, '-f', 'null', '-'],
      timeoutMs
    );
    if (code !== 0) return { status: 'error', error: `Silence detection failed (ffmpeg exit ${code}); the media may be corrupted.` };
    let openStart: number | null = null;
    for (const line of log.split('\n')) {
      const start = line.match(/silence_start: ([0-9.]+)/);
      const end = line.match(/silence_end: ([0-9.]+)/);
      if (start) openStart = Number(start[1]);
      if (end && openStart !== null) {
        silences.push({ startSec: Number(openStart.toFixed(3)), endSec: Number(Number(end[1]).toFixed(3)) });
        openStart = null;
      }
    }
    if (openStart !== null) {
      silences.push({ startSec: Number(openStart.toFixed(3)), endSec: Number(probe.durationSec.toFixed(3)) });
    }
  }

  const suggestedCuts: SuggestedCut[] = [
    ...silences.map((s) => ({ startSec: s.startSec, endSec: s.endSec, reason: 'silence' as const })),
    ...sceneChangesSec.map((t) => ({ startSec: Number(Math.max(0, t - 0.05).toFixed(3)), endSec: Number((t + 0.05).toFixed(3)), reason: 'scene-boundary' as const }))
  ].sort((a, b) => a.startSec - b.startSec);

  return { status: 'success', durationSec: probe.durationSec, sceneChangesSec, silences, suggestedCuts };
}
